import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const cs = Array.from(readFileSync(0, 'utf8'))
const n = cs.length
const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)

let i = 0, line = 1, col = 1
const tokens = []

class ScanError extends Error {}
function fail(l, c, reason) {
  throw new ScanError(`error: ${l}:${c}: ${reason}`)
}
function adv() {
  const c = cs[i++]
  if (c === '\n') { line++; col = 1 }
  else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
  else col++
  return c
}

function scanNumber() {
  const sl = line, sc = col, start = i
  const run = (pred) => {
    // digits with single underscores between digits; returns count of digits
    let k = 0
    while (pred(cs[i])) {
      adv(); k++
      if (cs[i] === '_' && pred(cs[i + 1])) adv()
    }
    return k
  }
  let ok = true
  if (cs[i] === '0' && /^[xXbBoO]$/.test(cs[i + 1] ?? '')) {
    const p = cs[i + 1].toLowerCase()
    const pred = p === 'x' ? isHex : p === 'b' ? (c) => c === '0' || c === '1' : (c) => c !== undefined && c >= '0' && c <= '7'
    adv(); adv()
    if (run(pred) === 0) ok = false
  } else {
    run(isDigit)
    if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); run(isDigit) }
    if (cs[i] === 'e' || cs[i] === 'E') {
      if (isDigit(cs[i + 1])) { adv(); run(isDigit) }
      else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { adv(); adv(); run(isDigit) }
    }
  }
  if (!ok || isIdChar(cs[i])) {
    while (isIdChar(cs[i])) adv()
    fail(sl, sc, `invalid number ${cs.slice(start, i).join('')}`)
  }
  tokens.push([sl, sc, 'number', cs.slice(start, i).join('')])
}

function scanString() {
  const sl = line, sc = col
  adv()
  let v = ''
  for (;;) {
    if (i >= n) fail(sl, sc, 'unterminated string')
    const c = cs[i]
    if (c === '\n') fail(line, col, 'newline in string')
    if (c === '"') { adv(); break }
    if (c !== '\\') { v += adv(); continue }
    const bl = line, bc = col
    adv()
    if (i >= n) fail(sl, sc, 'unterminated string')
    const e = cs[i]
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
    if (e in simple) { adv(); v += simple[e] }
    else if (e === 'x') {
      if (isHex(cs[i + 1]) && isHex(cs[i + 2])) {
        adv(); v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16)); adv(); adv()
      } else fail(bl, bc, 'invalid escape \\x')
    } else if (e === 'u') {
      let j = i + 1, h = ''
      if (cs[j] === '{') {
        j++
        while (isHex(cs[j])) h += cs[j++]
        if (cs[j] === '{' || cs[j] !== '}' || h === '' || parseInt(h, 16) > 0x10ffff) fail(bl, bc, 'invalid escape \\u')
        while (i <= j) adv()
        v += String.fromCodePoint(parseInt(h, 16))
      } else fail(bl, bc, 'invalid escape \\u')
    } else if (e === '\n') fail(bl, bc, 'invalid escape \\\n')
    else fail(bl, bc, `invalid escape \\${e}`)
  }
  tokens.push([sl, sc, 'string', JSON.stringify(v)])
}

function scanRaw() {
  const sl = line, sc = col
  adv(); adv()
  let v = ''
  for (;;) {
    if (i >= n) fail(sl, sc, 'unterminated string')
    const c = adv()
    if (c === '"') break
    v += c
  }
  tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
}

function scan() {
  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') { while (i < n && cs[i] !== '\n') adv(); continue }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }
    if (isDigit(c)) { scanNumber(); continue }
    if (c === 'r' && cs[i + 1] === '"') { scanRaw(); continue }
    if (isIdStart(c)) {
      const sl = line, sc = col, s = i
      while (isIdChar(cs[i])) adv()
      const t = cs.slice(s, i).join('')
      tokens.push([sl, sc, KEYWORDS.has(t) ? 'keyword' : 'ident', t])
      continue
    }
    if (c === '"') { scanString(); continue }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      const sl = line, sc = col
      adv(); adv()
      tokens.push([sl, sc, 'punct', two])
      continue
    }
    if (PUNCT1.includes(c)) {
      const sl = line, sc = col
      adv()
      tokens.push([sl, sc, 'punct', c])
      continue
    }
    fail(line, col, `unexpected character ${c}`)
  }
}

try {
  scan()
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}

let out = ''
if (mode === 'tokens') {
  for (const [l, c, k, b] of tokens) out += `${l}:${c} ${k} ${b}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string'])
    out += `${k} ${tokens.filter((t) => t[2] === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
