import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let names = null
  const set = new Set()
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      names = []
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (set.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        set.add(name)
        names.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!set.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  }
  if (names === null) fail('error: no candidates')
  return { names, ballots }
}

function run(mode, { names, ballots }) {
  const cont = new Set(names)
  const hist = new Map(names.map((c) => [c, []]))
  const out = []
  let rounds = 0
  let result
  for (;;) {
    rounds++
    const cnt = new Map([...cont].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((x) => cont.has(x))
      if (c !== undefined) { cnt.set(c, cnt.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of cnt) hist.get(c).push(v)
    const list = [...cnt.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    out.push(`round ${rounds}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
    if (active === 0n) { result = 'no winner'; break }
    const win = list.find(([, v]) => v * 2n > active)
    if (win) { result = `winner ${win[0]}`; break }
    let min = list[list.length - 1][1]
    let tied = list.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; tied.length > 1 && r < rounds; r++) {
      const m = tied.reduce((a, c) => (hist.get(c)[r] < a ? hist.get(c)[r] : a), hist.get(tied[0])[r])
      const keep = tied.filter((c) => hist.get(c)[r] === m)
      if (keep.length < tied.length) { tied = keep; r = -1 }
    }
    const elim = tied.reduce((a, c) => (c > a ? c : a))
    cont.delete(elim)
    out.push(`eliminated ${elim}`)
  }
  out.push(result)
  return mode === 'tally' ? `rounds ${rounds}\n${result}\n` : out.join('\n') + '\n'
}

try {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
  const text = readFileSync(0, 'utf8')
  process.stdout.write(run(args[0], parse(text)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
