        out.push(resolve(line.slice(0, sp), line.slice(sp + 1)))
      }
    } catch (e) {
      if (e instanceof CheckError) throw new CheckError(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
