export class CheckError extends Error {}

export function parse(s) {
  const u = {}
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { u.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    m = /^\/\/([^/?#]*)/.exec(s)
    u.authority = m[1]
    s = s.slice(m[0].length)
  }
  m = /^[^?#]*/.exec(s)
  u.path = m[0]
  s = s.slice(m[0].length)
  if (s.startsWith('?')) {
    m = /^\?([^#]*)/.exec(s)
    u.query = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('#')) u.fragment = s.slice(1)
  return u
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const hp = a.slice(at + 1)
  const rb = hp.lastIndexOf(']')
  const colon = hp.indexOf(':', rb + 1)
  if (colon < 0) return { userinfo, host: hp }
  return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
}

const bad = /%(?![0-9A-Fa-f]{2})/
function check(label, v) {
  if (v !== undefined && bad.test(v)) throw new CheckError(`the ${label} has a truncated percent-encoding`)
}

function pct(v) {
  return v.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lower = (v) => v.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, out.lastIndexOf('/') < 0 ? 0 : out.lastIndexOf('/'))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const j = inp.indexOf('/', 1)
      const seg = j < 0 ? inp : inp.slice(0, j)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function serialize(u) {
  let r = ''
  if (u.scheme !== undefined) r += u.scheme + ':'
  if (u.authority !== undefined) r += '//' + u.authority
  r += u.path
  if (u.query !== undefined) r += '?' + u.query
  if (u.fragment !== undefined) r += '#' + u.fragment
  return r
}

export function normalize(u) {
  let auth
  if (u.authority !== undefined) auth = splitAuthority(u.authority)
  check('path', u.path)
  if (auth) { check('userinfo', auth.userinfo); check('host', auth.host) }
  check('query', u.query)
  check('fragment', u.fragment)
  const r = {}
  if (u.scheme !== undefined) r.scheme = lower(u.scheme)
  if (auth) {
    let a = ''
    if (auth.userinfo !== undefined) a += pct(auth.userinfo) + '@'
    a += lower(pct(auth.host))
    if (auth.port !== undefined) {
      const port = pct(auth.port)
      const def = r.scheme !== undefined ? DEFAULT_PORT[r.scheme] : undefined
      if (port !== '' && port !== def) a += ':' + port
    }
    r.authority = a
  }
  r.path = removeDots(pct(u.path))
  if (r.authority !== undefined && r.path === '') r.path = '/'
  if (u.query !== undefined) r.query = pct(u.query)
  if (u.fragment !== undefined) r.fragment = pct(u.fragment)
  return serialize(r)
}

export function resolve(baseStr, refStr) {
  const b = parse(baseStr)
  if (b.scheme === undefined) throw new CheckError('the base has no scheme')
  const r = parse(refStr)
  let t
  if (r.scheme !== undefined) {
    t = { ...r, path: removeDots(r.path) }
  } else if (r.authority !== undefined) {
    t = { scheme: b.scheme, authority: r.authority, path: removeDots(r.path), query: r.query, fragment: r.fragment }
  } else if (r.path === '') {
    t = { scheme: b.scheme, authority: b.authority, path: b.path, query: r.query !== undefined ? r.query : b.query, fragment: r.fragment }
  } else {
    let path
    if (r.path.startsWith('/')) path = r.path
    else if (b.authority !== undefined && b.path === '') path = '/' + r.path
    else {
      const i = b.path.lastIndexOf('/')
      path = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
    }
    t = { scheme: b.scheme, authority: b.authority, path: removeDots(path), query: r.query, fragment: r.fragment }
  }
  return normalize(t)
}
