    m = /^\/\/([^/?#]*)/.exec(s)
    u.authority = m[1]
    s = s.slice(m[0].length)
  }
  m = /^[^?#]*/.exec(s)
  u.path = m[0]
  s = s.slice(m[0].length)
  if (s.startsWith('?')) {
    m = /^\?([^#]*)/.exec(s)
    u.query = m[1]
    s = s.slice(m[0].length)
  }
  if (s.startsWith('#')) u.fragment = s.slice(1)
  return u
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const hp = a.slice(at + 1)
  const rb = hp.lastIndexOf(']')
  const colon = hp.indexOf(':', rb + 1)
  if (colon < 0) return { userinfo, host: hp }
  return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
