const bad = /%(?![0-9A-Fa-f]{2})/
function check(label, v) {
  if (v !== undefined && bad.test(v)) throw new CheckError(`the ${label} has a truncated percent-encoding`)
}

function pct(v) {
  return v.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
