  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function serialize(u) {
  let r = ''
  if (u.scheme !== undefined) r += u.scheme + ':'
  if (u.authority !== undefined) r += '//' + u.authority
  r += u.path
  if (u.query !== undefined) r += '?' + u.query
  if (u.fragment !== undefined) r += '#' + u.fragment
  return r
}

export function normalize(u) {
  let auth
  if (u.authority !== undefined) auth = splitAuthority(u.authority)
  check('path', u.path)
  if (auth) { check('userinfo', auth.userinfo); check('host', auth.host) }
  check('query', u.query)
  check('fragment', u.fragment)
  const r = {}
  if (u.scheme !== undefined) r.scheme = lower(u.scheme)
  if (auth) {
    let a = ''
    if (auth.userinfo !== undefined) a += pct(auth.userinfo) + '@'
    a += lower(pct(auth.host))
