    r.authority = a
  }
  r.path = removeDots(pct(u.path))
  if (r.authority !== undefined && r.path === '') r.path = '/'
  if (u.query !== undefined) r.query = pct(u.query)
  if (u.fragment !== undefined) r.fragment = pct(u.fragment)
  return serialize(r)
}

export function resolve(baseStr, refStr) {
  const b = parse(baseStr)
  if (b.scheme === undefined) throw new CheckError('the base has no scheme')
  const r = parse(refStr)
  let t
  if (r.scheme !== undefined) {
    t = { ...r, path: removeDots(r.path) }
  } else if (r.authority !== undefined) {
    t = { scheme: b.scheme, authority: r.authority, path: removeDots(r.path), query: r.query, fragment: r.fragment }
  } else if (r.path === '') {
    t = { scheme: b.scheme, authority: b.authority, path: b.path, query: r.query !== undefined ? r.query : b.query, fragment: r.fragment }
  } else {
    let path
    if (r.path.startsWith('/')) path = r.path
    else if (b.authority !== undefined && b.path === '') path = '/' + r.path
    else {
      const i = b.path.lastIndexOf('/')
      path = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
    }
    t = { scheme: b.scheme, authority: b.authority, path: removeDots(path), query: r.query, fragment: r.fragment }
  }
  return normalize(t)
}
