      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function sideLines(cs, side, rs, re) {
  const f = cs[0], l = cs[cs.length - 1]
  return side.slice(f.ss - (f.bs - rs), l.se + (re - l.be))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const docs = parse(readFileSync(0, 'utf8'))
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const out = []
  let conflict = false
  const emit = (kind, lines, extra) => {
    if (mode === 'regions') out.push(extra || `${kind} ${lines.length}`)
    else out.push(...lines)
  }
  let pos = 0, k = 0
  const stable = (to) => {
    if (to > pos) emit('stable', base.slice(pos, to))
    pos = to
  }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
