      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    if (group.length === 1) {
      const c = group[0]
      const lines = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
