    const m = mc.length ? sideLines(mc, mine, rs, re) : baseL
    const t = tc.length ? sideLines(tc, theirs, rs, re) : baseL
    if (same(m, t)) emit('both', m)
    else if (same(m, baseL)) emit('theirs', t)
    else if (same(t, baseL)) emit('mine', m)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseL)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    }
  }
  stable(base.length)
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
