#!/usr/bin/env node
import fs from 'node:fs'
import { parseFormula, collectDeps } from './formula.js'
import { evaluateSheet, formatValue } from './eval.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = fs.readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const addr = m[0]
  if (!/^[A-Za-z]{1,2}[0-9]{1,3}$/.test(addr) || Number(addr.replace(/^[A-Za-z]+/, '')) < 1) {
    fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  }
  const key = addr.toUpperCase()
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  const content = line.slice(addr.length).replace(/^[ \t]*/, '')
  cells.set(key, content)
})

const cmp = (a, b) => {
  const ca = /^[A-Z]+/.exec(a)[0], cb = /^[A-Z]+/.exec(b)[0]
  if (ca !== cb) return ca.length - cb.length || (ca < cb ? -1 : 1)
  return Number(a.slice(ca.length)) - Number(b.slice(cb.length))
}
const keys = [...cells.keys()].sort(cmp)
let out = ''
if (mode === 'values') {
  const vals = evaluateSheet(cells)
  for (const k of keys) out += `${k}=${formatValue(vals.get(k))}\n`
} else {
  for (const k of keys) {
    const c = cells.get(k)
    let names = []
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      if (ast) names = collectDeps(ast).sort(cmp)
    }
    out += `${k}:${names.map((n) => ' ' + n).join('')}\n`
  }
}
process.stdout.write(out)
