export const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function validAddr(w) {
  const m = ADDR.exec(w)
  if (!m || Number(m[2]) < 1) return null
  return m[1].toUpperCase() + String(Number(m[2]))
}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the body.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = new Error('syntax')

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: term() }
    }
