  const freeAt = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0
  let left = names.length
  let makespan = 0
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((k) => !done.has(k) && D.get(k).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      done.set(task, f)
      freeAt[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      makespan = Math.max(makespan, f)
      left--
    }
    if (left === 0) break
    const next = freeAt.filter((f) => f > t)
    // also pending finishes of started tasks matter only via workers freeing
    t = Math.min(...next)
  }
  ran.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
