const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

const newTable = () => ({ kind: 'table', map: new Map(), header: false })
const fail = (m) => { throw new ParseError(m) }

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get end() { return this.i >= this.s.length }
  get ch() { return this.s[this.i] }
  ws() { while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++ }
  atComment() { return this.end || this.ch === '#' || this.ch === ';' }

  string() {
    const q = this.ch
    this.i++
    let out = ''
    for (;;) {
      if (this.end) fail('unterminated string')
      const c = this.ch
      if (c === q) { this.i++; return out }
      if (q === '"' && c === '\\') {
        this.i++
        if (this.end) fail('unterminated string')
        const e = this.ch
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; this.i++ }
        else if (e === 'u') {
          const h = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 5
        } else fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i)))
      } else { out += c; this.i++ }
    }
  }

  name() {
    if (this.end) fail('expected a name')
    if (this.ch === '"' || this.ch === "'") return this.string()
    const st = this.i
    while (!this.end && BARE.test(this.ch)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.ch === '.') { this.i++; this.ws(); parts.push(this.name()) } else { this.i = save; return parts }
    }
  }

  value(base) {
    if (this.atComment() || ',]}'.includes(this.ch)) fail('expected a value')
    const c = this.ch
    if (c === '"' || c === "'") return { kind: 'string', v: this.string() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (!this.end && !' \t,]};'.includes(this.ch)) this.i++
    const t = this.s.slice(st, this.i)
    if (t === 'true' || t === 'false') return { kind: 'boolean', v: t === 'true' }
    if (INT.test(t)) return { kind: 'integer', v: Number(t.replace(/_/g, '')) }
    if (FLOAT.test(t)) return { kind: 'float', v: Number(t.replace(/_/g, '')) }
    fail('invalid value ' + t)
  }

  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atComment()) fail('unterminated array')
      if (this.ch === ']') { this.i++; return { kind: 'array', items, aot: false } }
      items.push(this.value(base))
      this.ws()
      if (this.atComment()) fail('unterminated array')
      if (this.ch === ',') this.i++
      else if (this.ch !== ']') fail('unterminated array')
    }
  }

  inline(base) {
    this.i++
    const t = newTable()
    this.ws()
    if (this.atComment()) fail('unterminated inline table')
    if (this.ch === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atComment()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.atComment()) fail('unterminated inline table')
      if (this.ch !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(base.concat(keys))
      assign(t, base, keys, v)
      this.ws()
      if (this.atComment()) fail('unterminated inline table')
      if (this.ch === ',') this.i++
      else if (this.ch === '}') { this.i++; return t }
      else fail('unterminated inline table')
    }
  }
}

function step(node, key, path) {
  // descend into an existing child during a walk
  if (node.kind === 'table') return node
  if (node.kind === 'array' && node.aot) return node.items[node.items.length - 1]
  fail(path.join('.') + ' is not a table')
}

function walk(table, base, keys) {
  let cur = table
  for (let n = 0; n < keys.length; n++) {
    const k = keys[n]
    const path = base.concat(keys.slice(0, n + 1))
    let child = cur.map.get(k)
    if (!child) { child = newTable(); cur.map.set(k, child) }
    cur = step(child, k, path)
  }
  return cur
}

function assign(table, base, keys, v) {
  const parent = walk(table, base, keys.slice(0, -1))
  const k = keys[keys.length - 1]
  if (parent.map.has(k)) fail('key ' + base.concat(keys).join('.') + ' is defined twice')
  parent.map.set(k, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.end || L.ch === '#' || L.ch === ';') return
      if (L.ch === '[') {
        const dbl = raw[L.i + 1] === '['
        L.i += dbl ? 2 : 1
        L.ws()
        const keys = L.dotted()
        L.ws()
        for (let n = dbl ? 2 : 1; n > 0; n--) {
          if (L.ch !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atComment()) fail('trailing text after a table header')
        const parent = walk(root, [], keys.slice(0, -1))
        const k = keys[keys.length - 1]
        const ex = parent.map.get(k)
        const p = keys.join('.')
        if (dbl) {
          if (!ex) {
            const t = newTable(); t.header = true
            parent.map.set(k, { kind: 'array', items: [t], aot: true })
            cur = t
          } else if (ex.kind === 'array' && ex.aot) {
            const t = newTable(); t.header = true
            ex.items.push(t)
            cur = t
          } else fail(p + ' is not an array of tables')
        } else if (!ex) {
          const t = newTable(); t.header = true
          parent.map.set(k, t)
          cur = t
        } else if (ex.kind !== 'table') fail(p + ' is not a table')
        else if (ex.header) fail('table ' + p + ' is defined twice')
        else { ex.header = true; cur = ex }
        curPath = keys
        return
      }
      const keys = L.dotted()
      L.ws()
      if (L.end || L.ch !== '=') fail('expected key = value')
      L.i++
      L.ws()
      const v = L.value(curPath.concat(keys))
      L.ws()
      if (!L.atComment()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
