#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parser.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (t) => [...t.map.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.kind === 'table') {
    const ks = sorted(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.kind === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keyLines(n, path, out) {
  if (n.kind === 'table') {
    for (const k of sorted(n)) {
      const p = path === null ? k : path + '.' + k
      const c = n.map.get(k)
      out.push(p + ' ' + c.kind)
      keyLines(c, p, out)
    }
  } else if (n.kind === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.kind)
      keyLines(c, p, out)
    })
  }
}

try {
  const root = parse(readFileSync(0, 'utf8'))
  if (args[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keyLines(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
