import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const NUM = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim()
    if (t === '' || t.startsWith('#')) continue
    const w = t.split(/\s+/)
    const fail = (r) => { throw new Fail(`line ${i + 1}: ${r}`) }
    const num = (v, field, least) => {
      if (!NUM.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = w[0]
    if (d === 'bucket' || d === 'window') {
      const n = d === 'bucket' ? 5 : 4
      if (w.length !== n) fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      if (events.length) fail('declarations must come before the first event')
      if (!NAME.test(w[1])) fail(`invalid policy name ${w[1]}`)
      let p
      if (d === 'bucket') p = { kind: 'bucket', name: w[1], cap: num(w[2], 'capacity', 1), refill: num(w[3], 'refill', 0), per: num(w[4], 'per', 1) }
      else p = { kind: 'window', name: w[1], limit: num(w[2], 'limit', 0), span: num(w[3], 'span', 1) }
      if (policies.has(w[1])) fail(`policy ${w[1]} is declared twice`)
      policies.set(w[1], p)
    } else if (d === 'route') {
      if (w.length < 3) fail('expected route <prefix> <policy>...')
      if (events.length) fail('declarations must come before the first event')
      if (!NAME.test(w[1])) fail(`invalid route prefix ${w[1]}`)
      if (routes.has(w[1])) fail(`prefix ${w[1]} is routed twice`)
      for (const p of w.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
      routes.set(w[1], w.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (w.length !== 3) fail('expected event <tick> <key>')
      const tick = num(w[1], 'tick', 0)
      if (!NAME.test(w[2])) fail(`invalid key ${w[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: w[2] })
    } else fail(`unknown directive ${d}`)
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map() // policy -> Map(key -> state)
  const stateOf = (p, key, tick) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.cap * p.per, last: tick } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const advance = (p, s, tick) => {
    if (p.kind === 'bucket') {
      const max = p.cap * p.per
      s.num += p.refill * (tick - s.last)
      if (s.num > max) s.num = max
      s.last = tick
    } else {
      const cut = tick - p.span
      s.ticks = s.ticks.filter((x) => x > cut)
    }
  }
  const allows = (p, s) => (p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit)
  const record = (p, s, tick) => {
    if (p.kind === 'bucket') s.num -= p.per
    else s.ticks.push(tick)
  }
  const prefixes = [...routes.keys()]
  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const pf of prefixes) if (key.startsWith(pf) && (best === null || pf.length > best.length)) best = pf
    let refused = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map((p) => stateOf(p, key, tick))
      ps.forEach((p, i) => advance(p, ss[i], tick))
      for (let i = 0; i < ps.length; i++) if (!allows(ps[i], ss[i])) { refused = ps[i]; break }
      if (!refused) ps.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = per.get(key) || { a: 0, d: 0 }
    per.set(key, c)
    if (refused) { c.d++; td++; out.push(`${tick} ${key} deny ${refused.name}`) }
    else { c.a++; ta++; out.push(`${tick} ${key} allow`) }
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`).join('') + `total allowed=${ta} denied=${td}\n`
}

let result
try {
  result = run(parse(readFileSync(0, 'utf8')))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
