const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.c; return c === undefined || c === '#' || c === ';' }

  string() {
    const q = this.c
    this.i++
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      const cp = String.fromCodePoint(e.codePointAt(0))
      this.i += cp.length
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + cp)
    }
  }

  name() {
    this.ws()
    const c = this.c
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isBare(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      this.ws()
      if (this.c !== '.') return parts
      this.i++
      parts.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const int = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${int}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')).toString() }
    if (new RegExp(`^[+-]?${int}(?:\\.${int}(?:[eE][+-]?${int})?|[eE][+-]?${int})$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    fail('invalid value ' + w)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value(prefix))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') continue
      fail('trailing text after a value')
    }
  }

  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(prefix.concat(parts))
      assign(tbl, prefix, parts, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return tbl }
      fail('trailing text after a value')
    }
  }
}

const root = newTable()

function descend(cur, key, path) {
  const n = cur.m.get(key)
  if (!n) { const t = newTable(); cur.m.set(key, t); return t }
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  fail(path.join('.') + ' is not a table')
}

function assign(base, basePath, parts, v) {
  let cur = base
  for (let k = 0; k < parts.length - 1; k++) cur = descend(cur, parts[k], basePath.concat(parts.slice(0, k + 1)))
  const last = parts[parts.length - 1]
  if (cur.m.has(last)) fail('key ' + basePath.concat(parts).join('.') + ' is defined twice')
  cur.m.set(last, v)
}

let current = root
let currentPath = []

function header(L) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  const parts = L.dotted()
  L.ws()
  if (L.c !== ']') fail('unterminated table header')
  L.i++
  if (aot) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  let cur = root
  for (let k = 0; k < parts.length - 1; k++) cur = descend(cur, parts[k], parts.slice(0, k + 1))
  const last = parts[parts.length - 1]
  const n = cur.m.get(last)
  if (aot) {
    if (!n) {
      const t = newTable()
      cur.m.set(last, { t: 'array', items: [t], aot: true })
      current = t
    } else if (n.t === 'array' && n.aot) {
      const t = newTable()
      n.items.push(t)
      current = t
    } else fail(parts.join('.') + ' is not an array of tables')
  } else if (!n) {
    const t = newTable()
    t.header = true
    cur.m.set(last, t)
    current = t
  } else if (n.t === 'table') {
    if (n.header) fail('table ' + parts.join('.') + ' is defined twice')
    n.header = true
    current = n
  } else fail(parts.join('.') + ' is not a table')
  currentPath = parts
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') return
      if (L.c === '[') return header(L)
      const parts = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value(currentPath.concat(parts))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(current, currentPath, parts, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `error: line ${idx + 1}: ${e.message}`
      throw e
    }
  })
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'string': return JSON.stringify(n.v)
    case 'float': return JSON.stringify(n.v)
    default: return String(n.v)
  }
}

function keys(n, path, out) {
  const walk = (child, p) => {
    out.push(`${p} ${child.t}`)
    keys(child, p, out)
  }
  if (n.t === 'table') {
    for (const k of sortedKeys(n)) walk(n.m.get(k), path === '' ? k : path + '.' + k)
  } else if (n.t === 'array') {
    n.items.forEach((x, i) => walk(x, `${path}[${i}]`))
  }
}

try {
  parse(fs.readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
if (mode === 'json') {
  process.stdout.write(toJson(root, 0) + '\n')
} else {
  const out = []
  keys(root, '', out)
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}
"}

