{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`line ${n}: expected candidates <name>...`)
    names = []
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) fail(`line ${n}: invalid candidate name ${nm}`)
      if (known.has(nm)) fail(`line ${n}: candidate ${nm} is declared twice`)
      known.add(nm)
      names.push(nm)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!known.has(nm)) fail(`line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`line ${n}: unknown directive ${t[0]}`)
  }
})
if (names === null) fail('no candidates')

const cont = new Set(names)
const history = []
let out = ''
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  history.push(counts)
  const list = [...counts.keys()].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  out += `round ${roundNo}: ${list.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}\n`
  if (active === 0n) { result = 'no winner'; break }
  const w = list.find((c) => counts.get(c) * 2n > active)
  if (w !== undefined) { result = `winner ${w}`; break }
  let s = [...cont]
  for (const h of history) {
    if (s.length === 1) break
    let min = null
    for (const c of s) if (min === null || h.get(c) < min) min = h.get(c)
    s = s.filter((c) => h.get(c) === min)
  }
  const e = s.reduce((a, b) => (a > b ? a : b))
  cont.delete(e)
  out += `eliminated ${e}\n`
}
process.stdout.write(mode === 'rounds' ? `${out}${result}\n` : `rounds ${roundNo}\n${result}\n`)
EOF
